function getAcademicGroupE() {
  const allE = [];
  const subjectIds = [
    'subj-eng1',
    'subj-eng2',
    'subj-techwrite',
    'subj-econ',
    'subj-culture',
    'subj-national',
    'subj-military',
    'subj-history',
    'subj-entrepreneur',
    'subj-workshops'
  ];

  for (const sId of subjectIds) {
    // 1. Get existing authentic questions from db
    const existingMid = db.questions.filter(q => q.quizId === `quiz-${sId}-mid`);
    const existingFin = db.questions.filter(q => q.quizId === `quiz-${sId}-final`);

    allE.push(...existingMid);
    allE.push(...existingFin);

    // 2. Add supplements
    const supp = supplementsE[sId];
    if (supp) {
      // Mid supplement
      const midNeeded = 32 - existingMid.length;
      for (let i = 0; i < midNeeded; i++) {
        if (i < supp.mid.length) {
          const item = supp.mid[i];
          const newId = `${sId.replace('subj-','').toUpperCase()}-MID-SUPP-${String(i+1).padStart(2, '0')}`;
          allE.push(createQuestion(newId, sId, false, item[0], item[1], item[2], item[3], item[4], item[5], 'Medium', 'University Exam Archive.pdf', existingMid.length + i));
        }
      }

      // Final supplement
      const finNeeded = 52 - existingFin.length;
      for (let i = 0; i < finNeeded; i++) {
        if (i < supp.final.length) {
          const item = supp.final[i];
          const newId = `${sId.replace('subj-','').toUpperCase()}-FIN-SUPP-${String(i+1).padStart(2, '0')}`;
          allE.push(createQuestion(newId, sId, true, item[0], item[1], item[2], item[3], item[4], item[5], 'Medium', 'University Final Exam Archive.pdf', existingFin.length + i));
        }
      }
    }
  }

  return allE;
}

module.exports = { getAcademicGroupE };
